long long countPairs(int n, vector<array<long long,3>>& e, long long L, long long R){
    const long long INF = LLONG_MAX/4;
    vector<vector<long long>> d(n, vector<long long>(n, INF));
    for(int i=0;i<n;i++) d[i][i]=0;
    for(auto& x: e){ int u=x[0]-1, v=x[1]-1; d[u][v]=d[v][u]=min(d[u][v], x[2]); }
    for(int k=0;k<n;k++) for(int i=0;i<n;i++) if(d[i][k]<INF)
        for(int j=0;j<n;j++) if(d[k][j]<INF) d[i][j]=min(d[i][j], d[i][k]+d[k][j]);
    long long c=0;
    for(int i=0;i<n;i++) for(int j=i+1;j<n;j++) if(d[i][j]<INF && d[i][j]>=L && d[i][j]<=R) c++;
    return c;
}

long long countSwaps(vector<int>& p, long long MOD){ // p is 1-indexed values
    int n=p.size(); vector<bool> vis(n,false); map<long long,long long> cnt;
    for(int i=0;i<n;i++) if(!vis[i]){ long long len=0; int j=i; while(!vis[j]){vis[j]=true; j=p[j]-1; len++;} cnt[len]++; }
    int cycles=0; for(auto& kv:cnt) cycles+=kv.second;
    if(cycles==1){ if(n>=3) return n%MOD; return (n==2)?1%MOD:0; }
    auto it=cnt.rbegin(); long long a=it->first, ka=it->second;
    if(ka>=2) return (long long)((__int128)ka*(ka-1)/2 %MOD * (a%MOD) %MOD * (a%MOD) %MOD);
    ++it; long long b=it->first, kb=it->second;
    return (long long)((__int128)a*b%MOD*kb%MOD);
}

long long minOps(vector<vector<int>> a, int K){
    int n=a.size(), m=a[0].size(); long long ans=0;
    priority_queue<array<int,3>> pq;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) pq.push({a[i][j],i,j});
    int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
    while(!pq.empty()){
        auto [v,r,c]=pq.top(); pq.pop();
        if(v!=a[r][c]) continue;
        for(int d=0;d<4;d++){ int nr=r+dr[d], nc=c+dc[d];
            if(nr<0||nc<0||nr>=n||nc>=m) continue;
            if(a[nr][nc] < v-K){ ans += (v-K) - a[nr][nc]; a[nr][nc]=v-K; pq.push({a[nr][nc],nr,nc}); }
        }
    }
    return ans;
}

const int MOD=1e9+7;
long long countWays(vector<string>& g){
    int n=g.size(), m=g[0].size(), k=0, sr=0, sc=0;
    vector<vector<int>> kid(n, vector<int>(m,-1));
    for(int i=0;i<n;i++) for(int j=0;j<m;j++){ if(g[i][j]=='K') kid[i][j]=k++; if(g[i][j]=='X'){sr=i;sc=j;} }
    int S=1<<k, full=S-1;
    vector<int> dist(n*m*S,-1); vector<long long> ways(n*m*S,0);
    auto id=[&](int r,int c,int s){ return (r*m+c)*S+s; };
    queue<array<int,3>> q; dist[id(sr,sc,0)]=0; ways[id(sr,sc,0)]=1; q.push({sr,sc,0});
    int dr[4]={1,-1,0,0}, dc[4]={0,0,1,-1};
    while(!q.empty()){
        auto [r,c,s]=q.front(); q.pop(); int u=id(r,c,s);
        vector<array<int,3>> nxt;
        for(int d=0;d<4;d++){ int nr=r+dr[d], nc=c+dc[d];
            if(nr>=0&&nc>=0&&nr<n&&nc<m&&g[nr][nc]!='#') nxt.push_back({nr,nc,s}); }
        if(kid[r][c]>=0 && !(s>>kid[r][c]&1)) nxt.push_back({r,c,s|1<<kid[r][c]});
        for(auto& t: nxt){ int v=id(t[0],t[1],t[2]);
            if(dist[v]==-1){ dist[v]=dist[u]+1; ways[v]=ways[u]; q.push(t); }
            else if(dist[v]==dist[u]+1) ways[v]=(ways[v]+ways[u])%MOD; }
    }
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) if(g[i][j]=='O') return ways[id(i,j,full)];
    return 0;
}

int countNodes(int n, vector<int>& a, vector<long long>& b, long long m){ // a,b are 1-indexed (size n+1)
    const long long INF=LLONG_MAX/4; int sz=1; while(sz<n+2) sz<<=1;
    vector<long long> t(2*sz, INF), dist(n+1, INF);
    auto upd=[&](int i,long long v){ for(t[i+=sz]=v, i>>=1; i; i>>=1) t[i]=min(t[2*i],t[2*i+1]); };
    auto qry=[&](int l,int r){ long long res=INF; for(l+=sz, r+=sz+1; l<r; l>>=1, r>>=1){
        if(l&1) res=min(res,t[l++]); if(r&1) res=min(res,t[--r]); } return res; };
    vector<vector<int>> dv(n+1);
    for(int d=1; d<=n; d++) for(int y=2*d; y<=n; y+=d) dv[y].push_back(d);
    if(n<2) return 0;
    dist[2]=0; upd(2, b[2]);
    for(int y=3;y<=n;y++){
        int lo=max(1,y-a[y]), cur=lo; long long best=INF;
        for(int d: dv[y]) if(d>=lo){ if(cur<=d-1) best=min(best,qry(cur,d-1)); cur=d+1; }
        if(cur<=y-1) best=min(best,qry(cur,y-1));
        if(best<INF){ dist[y]=best; upd(y, best+b[y]); }
    }
    int c=0; for(int i=1;i<=n;i++) if(dist[i]<=m) c++;
    return c;
}

// n positions 0..n-1, start p (0-indexed), banned positions, window length k
vector<int> minReverseOperations(int n, int p, vector<int>& banned, int k){
    vector<int> ans(n,-1); vector<bool> ban(n,false);
    for(int b: banned) ban[b]=true;
    set<int> free_[2];
    for(int i=0;i<n;i++) if(i!=p && !ban[i]) free_[i%2].insert(i);
    queue<int> q; q.push(p); ans[p]=0;
    while(!q.empty()){
        int i=q.front(); q.pop();
        int lo = 2*max(0,i-k+1)+k-1-i, hi = 2*min(i,n-k)+k-1-i;
        auto& s = free_[((lo%2)+2)%2];
        for(auto it=s.lower_bound(lo); it!=s.end() && *it<=hi; it=s.erase(it)){
            ans[*it]=ans[i]+1; q.push(*it);
        }
    }
    return ans;
}

long long bestDiameter(int n, vector<array<long long,3>>& E){ // nodes 1..n, tree edges (u,v,w)
    vector<vector<pair<int,int>>> g(n+1); // (to, edge id)
    for(int i=0;i<(int)E.size();i++){ g[E[i][0]].push_back({(int)E[i][1],i}); g[E[i][1]].push_back({(int)E[i][0],i}); }
    long long best=LLONG_MAX;
    for(int cut=0; cut<(int)E.size(); cut++){
        auto bfs=[&](int s, vector<long long>& d, vector<int>& comp){ d.assign(n+1,-1); comp.clear(); d[s]=0;
            vector<int> st={s}; while(!st.empty()){ int x=st.back(); st.pop_back(); comp.push_back(x);
                for(auto [y,id]: g[x]) if(id!=cut && d[y]<0){ d[y]=d[x]+E[id][2]; st.push_back(y);} } };
        auto info=[&](int s, long long& dia, long long& rad){ vector<long long> d0,da,db; vector<int> c;
            bfs(s,d0,c); int a=s; for(int x:c) if(d0[x]>d0[a]) a=x;
            bfs(a,da,c); int b=a; for(int x:c) if(da[x]>da[b]) b=x;
            bfs(b,db,c); dia=da[b]; rad=LLONG_MAX; for(int x:c) rad=min(rad,max(da[x],db[x])); };
        long long d1,r1,d2,r2; info(E[cut][0],d1,r1); info(E[cut][1],d2,r2);
        best=min(best, max({d1,d2,r1+E[cut][2]+r2}));
    }
    return best;
}

int maxRemaining(vector<int> a){
    int ones=0; vector<int> od, ev;
    for(int x: a){ if(x==1){ if(ones++) continue; } (x%2? od: ev).push_back(x); }
    int mx=2; for(int x: a) mx=max(mx,2*x);
    vector<bool> comp(mx+1,false); comp[0]=comp[1]=true;
    for(int i=2;(long long)i*i<=mx;i++) if(!comp[i]) for(int j=i*i;j<=mx;j+=i) comp[j]=true;
    int L=od.size(), R=ev.size(); vector<vector<int>> adj(L);
    for(int i=0;i<L;i++) for(int j=0;j<R;j++) if(!comp[od[i]+ev[j]]) adj[i].push_back(j);
    vector<int> mt(R,-1); vector<char> used;
    function<bool(int)> tryK=[&](int v){ for(int u: adj[v]) if(!used[u]){ used[u]=1;
        if(mt[u]==-1 || tryK(mt[u])){ mt[u]=v; return true; } } return false; };
    int match=0; for(int v=0;v<L;v++){ used.assign(R,0); if(tryK(v)) match++; }
    return L+R-match;
}

