int contentParity(vector<int>& g, vector<int>& s){
    int total=0;
    for(int par=0; par<2; par++){
        vector<int> G,S;
        for(int x: g) if(((x%2)+2)%2==par) G.push_back(x);
        for(int x: s) if(((x%2)+2)%2==par) S.push_back(x);
        sort(G.begin(),G.end()); sort(S.begin(),S.end());
        size_t i=0, j=0;
        while(i<G.size() && j<S.size()){ if(S[j]>=G[i]) i++; j++; }
        total+=i;
    }
    return total;
}

