double fractionalKnapsack(long long W, vector<pair<long long,long long>> it){ // (value, weight)
    sort(it.begin(), it.end(), [](auto& a, auto& b){ return a.first*b.second > b.first*a.second; });
    double ans=0;
    for(auto& [v,w]: it){
        if(W<=0) break;
        if(w<=W){ ans+=v; W-=w; } else { ans+=(double)v*W/w; W=0; }
    }
    return ans;
}

