    sort(id.begin(), id.end(), [&](int a,int b){ return power[a]<power[b]; });
    int cnt=0;
    for(int i: id){ if(e<power[i]) break; e+=bonus[i]; cnt++; }
    return cnt;
}

int foldsNeeded(long long from, long long to){ // each fold leaves a size in [ceil(from/2), from-1]
    if(to>from) return -1; int k=0;
    while(from>to){ from=(from+1)/2; k++; }
    return k;
}
int minFolds(long long h, long long w, long long h1, long long w1){
    int a=foldsNeeded(h,h1), b=foldsNeeded(w,w1);
    return (a<0||b<0) ? -1 : a+b;
}

int minProcessingTime(vector<int> p, vector<int> t){
    sort(p.begin(), p.end()); sort(t.rbegin(), t.rend());
    int ans=0;
    for(size_t i=0;i<p.size();i++) ans=max(ans, p[i]+t[4*i]);
    return ans;
}

long long twoCity(vector<pair<long long,long long>> c){ // (costA, costB), size 2N
    sort(c.begin(), c.end(), [](auto& x, auto& y){ return x.first-x.second < y.first-y.second; });
    long long s=0; int n=c.size()/2;
    for(int i=0;i<(int)c.size();i++) s += (i<n) ? c[i].first : c[i].second;
    return s;
}

long long minOps(vector<long long>& a, long long k){
    long long s=0;
    for(long long x: a){ if(x<k) s+=k-x; else { long long r=x%k; s+=min(r,k-r); } }
    return s;
}

long long minCost(vector<long long> c, long long V){ // pay two, get a third (not more expensive) free; at most V times
    sort(c.rbegin(), c.rend()); long long total=0;
    for(long long i=0;i<(long long)c.size();i++){
        bool isFree = (i%3==2) && (i/3 < V);
        if(!isFree) total+=c[i];
    }
    return total;
}

long long minWork(vector<long long>& a){
    long long carry=0, work=0;
    for(long long x: a){ carry+=x; work+=llabs(carry); }
    return work;
}

int minPlatforms(vector<int> arr, vector<int> dep){
    sort(arr.begin(),arr.end()); sort(dep.begin(),dep.end());
    int n=arr.size(), i=0, j=0, cur=0, best=0;
    while(i<n){ if(arr[i]<=dep[j]){ cur++; i++; best=max(best,cur); } else { cur--; j++; } }
    return best;
}

